// First lexicographic window of the external columns; output diagnostic triples.
#include <algorithm>
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <numeric>
#include <queue>
#include <string_view>
#include <vector>
#include <fcntl.h>
#include <sys/mman.h>
#include <unistd.h>
using namespace std;namespace fs=std::filesystem;using U=uint32_t;using Q=uint64_t;
struct Cell{Q desc,rows;};struct Key{U start,len,req,off;unsigned char pred,eof;};struct Req{U id,lo,hi;};struct Occ{U pos,rank;unsigned char pred;};struct Pair{U pos,rank;};struct Triple{U pos,h,b;};constexpr U A=258;
Q reads(){ifstream f("/proc/self/io");string k;Q x;while(f>>k>>x)if(k=="read_bytes:")return x;abort();}template<class T>auto mapfile(fs::path p){auto sz=fs::file_size(p);int fd=open(p.c_str(),O_RDONLY);assert(fd>=0&&sz);auto v=(const T*)mmap(nullptr,sz,PROT_READ,MAP_PRIVATE,fd,0);close(fd);assert(v!=MAP_FAILED);return v;}
int main(int ac,char**av){assert(ac==7);fs::path tape=av[1],lists=av[2],aligned=av[3],corpus=av[4],output=av[5];Q n=fs::file_size(corpus),cap=stoull(av[6]);assert(n<=1010000000&&cap<=1100000);U m=fs::file_size(aligned)/4;auto c=mapfile<Cell>(tape/"cells.bin");Q live=fs::file_size(tape/"words.tape")+fs::file_size(tape/"cells.bin")+fs::file_size(lists/"loc.u32")+13ull*m;Q mass=0,rows=0;U hi=0;while(hi<A*A&&mass+c[hi].desc<=cap&&live+12*(1+rows+c[hi].rows)<=2*n){mass+=c[hi].desc;rows+=c[hi++].rows;}assert(mass&&rows<2000000);auto guard=[&]{assert(reads()<6*n);};assert(live+12*(1+rows)<=2*n);
 vector<char>arena;arena.reserve(64<<20);vector<Key>keys;keys.reserve(mass);vector<Req>req;ifstream words(tape/"words.tape",ios::binary);vector<char>w;U id,tag;while(words.read((char*)&id,4)){assert(words.read((char*)&tag,4));U len=tag&0x7fffffff;assert(len&&len<=(1<<20));bool eof=tag>>31;w.resize(len);assert(words.read(w.data(),len));bool used=false;for(U o=0;o<len-(eof?0:8);o++){U cell=(2+(unsigned char)w[o])*A+(o+1<len?2+(unsigned char)w[o+1]:1);if(cell>=hi)continue;if(!used){req.push_back({id,0,0});used=true;}assert(arena.size()+len-o<=64<<20);keys.push_back({(U)arena.size(),len-o,(U)req.size()-1,o,(unsigned char)(o?w[o-1]:0),(unsigned char)eof});arena.insert(arena.end(),w.begin()+o,w.end());}if(!(id%32768))guard();}assert(words.eof()&&keys.size()==mass);auto key=[&](Key a){return make_pair(string_view(arena.data()+a.start,a.len),a.eof);};sort(keys.begin(),keys.end(),[&](Key a,Key b){return key(a)<key(b);});
 auto loc=mapfile<U>(lists/"loc.u32");auto rr=mapfile<Pair>(lists/"pos-next.u32x2");auto pred=mapfile<unsigned char>(lists/"pred.u8");vector<U>order(req.size());iota(order.begin(),order.end(),0);sort(order.begin(),order.end(),[&](U a,U b){return req[a].id<req[b].id;});vector<Occ>occ;occ.reserve(rows);for(U ix:order){auto&r=req[ix];if(!(ix%8192))guard();r.lo=occ.size();for(U i=loc[r.id];i<loc[r.id+1];i++){assert(occ.size()<rows);occ.push_back({rr[i].pos,rr[i].rank,pred[i]});}r.hi=occ.size();assert(r.hi>r.lo);}munmap((void*)loc,fs::file_size(lists/"loc.u32"));munmap((void*)rr,8ull*m);munmap((void*)pred,m);
 auto al=mapfile<U>(aligned);const U B=64,blocks=(m+B-1)/B;vector<U>tree(2*blocks,UINT32_MAX);for(U i=0;i<m;i++)tree[blocks+i/B]=min(tree[blocks+i/B],al[i]);for(U i=blocks-1;i;i--)tree[i]=min(tree[i*2],tree[i*2+1]);madvise((void*)al,4ull*m,MADV_RANDOM);auto rmq=[&](U l,U r){assert(l<r&&r<=m);U h=UINT32_MAX;while(l<r&&l%B)h=min(h,al[l++]);while(l<r&&r%B)h=min(h,al[--r]);if(l<r){l=l/B+blocks;r=r/B+blocks;while(l<r){if(l&1)h=min(h,tree[l++]);if(r&1)h=min(h,tree[--r]);l/=2;r/=2;}}return h;};ofstream out(output,ios::binary);ifstream cf(corpus,ios::binary);cf.seekg(n-1);U last=cf.get();auto emit=[&](U p,U h,U b){Triple t{p,h,b};out.write((char*)&t,12);assert(out);};emit(n,0,last);U emitted=0,groups=0;using Node=tuple<U,U,U>;for(U i=0;i<mass;){auto a=key(keys[i]);U end=i+1;while(end<mass&&key(keys[end])==a)++end;U h=0;if(i){auto prev=key(keys[i-1]).first;while(h<prev.size()&&h<a.first.size()&&prev[h]==a.first[h])++h;}priority_queue<Node,vector<Node>,greater<Node>>q;for(U j=i;j<end;j++){U idx=req[keys[j].req].lo;q.emplace(occ[idx].rank,idx,j);}U prior=0;bool first=true;while(!q.empty()){auto [rank,idx,j]=q.top();q.pop();auto k=keys[j];if(!first){assert(prior&&prior<rank&&a.first.size()+a.second>=8);h=a.first.size()+a.second-8+rmq(prior,rank);}U pos=occ[idx].pos+k.off;emit(pos,h,!pos?256:(k.off?k.pred:occ[idx].pred));prior=rank;first=false;++emitted;if(!(emitted%65536))guard();if(++idx<req[k.req].hi)q.emplace(occ[idx].rank,idx,j);}i=end;++groups;}out.close();assert(out&&emitted==rows);guard();printf("WINDOW hi=%u descriptors=%llu groups=%u rows_plus_end=%u key_bytes=%zu reads=%llu counted_with_triples=%llu\n",hi,(unsigned long long)mass,groups,emitted+1,arena.size(),(unsigned long long)reads(),(unsigned long long)(live+12*(1+rows)));}
